; =============================================================================
; BANK $69 - Relocated SPECIAL breeding-recipe scanner (B2) +
;           FULL authored special table (B5)
; =============================================================================
; Generated by tools/build_breeding.py --emit-special
;
; ROADMAP Phase 2B / B5. The scanner (unchanged from B2/B3) walks
; to the $FF terminator with no hardcoded count. The whole table
; is authored data owned by build_breeding.py; edit any base entry
; in place or append new ones via breeding_special.json.
;
; The table below is the AUTHORED special table (B5):
;   825 base entries (vanilla ROM) with 3 in-place override(s)
;   + 2 appended recipe(s); single $FF terminator.
; Source of truth: extracted/breeding_special.json.
; Bank $16's vanilla special table is left byte-identical to the
; ROM (runtime-dead via the B2 rst $10 redirect).
; =============================================================================

SECTION "ROM Bank $069", ROMX[$4000], BANK[$69]
    db $69                        ; bank self-ID at $4000

; Jump table at $4001 (rst $10 with HL=$6900 dispatches entry 0)
    dw RelocatedSpecialScan

; -----------------------------------------------------------------------------
; RelocatedSpecialScan (B2) — faithful port of bank $16 special-table scan.
; Called via `ld hl,$6900; rst $10` from bank $16 (BreedPlusAndSpecial, in place of the
; old in-bank scan at $46F2-$470F). Plus value + parent family codes are already
; computed in bank $16 RAM before the call. On return, bank $16 clamps $DA77.
; Inputs  (RAM): $DA6F p1 species, $DA70 p2 species, $DA73 p1 family,
;                $DA74 p2 family, $DA77 offspring plus.
; Outputs (RAM): $DA71 result species (untouched if no match), $DA77 += plus_mod.
; -----------------------------------------------------------------------------
RelocatedSpecialScan:
    ld hl, RelocatedSpecialTable      ; relocated table: 825 base + appended (B3); scan to $FF
.scan:
    ld a, [hl]
    cp $ff                            ; $FF = end of table
    jr z, .done
    push hl
    call .checkentry                  ; port of BreedSpecialEntryCheck
    pop hl
    ld a, [$da71]
    cp $ff
    jr nz, .done                      ; match found -> stop
    ld a, l
    add $05                           ; advance to next 5-byte entry
    ld l, a
    ld a, h
    adc $00
    ld h, a
    jr .scan
.done:
    ret                               ; back to bank $16 plus-clamp ($4710)

; Port of BreedSpecialEntryCheck ($471C): match one 5-byte entry against the parents.
.checkentry:
    ld a, [$da6f]                     ; parent 1 species (specific)
    cp [hl]
    jr z, .e2
    ld a, [$da73]                     ; parent 1 family code
    cp [hl]
    jr nz, .edone
.e2:
    inc hl
    ld a, [$da70]                     ; parent 2 species (specific)
    cp [hl]
    jr z, .e3
    ld a, [$da74]                     ; parent 2 family code
    cp [hl]
    jr nz, .edone
.e3:
    inc hl
    ld a, [$da77]                     ; offspring plus value
    cp [hl]
    jr c, .edone                      ; plus < threshold -> skip
    inc hl
    ld a, [hl]                        ; result species ID
    ld [$da71], a
    inc hl
    ld a, [$da77]
    add [hl]                          ; add plus modifier
    ld [$da77], a
.edone:
    ret

